mapper.select:
SELECT pdl.*, mp.name as plant_name, mp.alias as plant_alias, mp.image_url as plant_image_url, pd.name as disease_name, pd.type as disease_type, pd.image_url as disease_image_url, eu.name as creator_name FROM plant_disease_link pdl LEFT JOIN medicinal_plant mp ON pdl.plant_id = mp.id LEFT JOIN pest_disease pd ON pdl.pd_id = pd.id LEFT JOIN expert_user eu ON pdl.created_by = eu.id
AND mp.name LIKE CONCAT('%', #{plantName}, '%')
AND pd.name LIKE CONCAT('%', #{diseaseName}, '%')
AND pdl.vulnerability = #{vulnerability}
ORDER BY pdl.created_at DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE plant_disease_link SET 
    vulnerability = #{vulnerability}, 
    occurrence_season = #{occurrenceSeason}, 
    affected_parts = #{affectedParts}, 
    notes = #{notes}
WHERE id = #{id}
